// Release checks for .github/workflows/jusprin_release.yml.
//
//   node release.mjs version <Version.hpp>
//       Prints JusPrin's version, the one in Version.hpp.
//   node release.mjs check <Version.hpp> <releases.json>
//       Reads GitHub's release list (drafts included, as an authenticated
//       request returns it) and fails if this version was already published
//       or is not above every published JusPrin version. Prints key=value
//       lines for $GITHUB_OUTPUT: version, tag, prerelease, draft_id.
//
// Tags follow the update check's rule (ReleaseFeed.cpp): vX.Y.Z, or
// jusprin/vX.Y.Z as JusPrin 1.4.0 was tagged. New releases are tagged vX.Y.Z.

import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const SEMVER = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z.-]+)?$/;

export function parseVersion(text) {
    const match = SEMVER.exec(text);
    if (!match)
        return null;
    return {
        text,
        core: [Number(match[1]), Number(match[2]), Number(match[3])],
        prerelease: match[4] ? match[4].split('.') : [],
    };
}

// Semantic Versioning 2.0.0 precedence: a version with a pre-release part
// ranks below the same version without one.
export function compareVersions(a, b) {
    for (let i = 0; i < 3; ++i)
        if (a.core[i] !== b.core[i])
            return a.core[i] < b.core[i] ? -1 : 1;
    if (a.prerelease.length === 0 || b.prerelease.length === 0)
        return b.prerelease.length - a.prerelease.length;
    for (let i = 0; i < Math.min(a.prerelease.length, b.prerelease.length); ++i) {
        const x = a.prerelease[i], y = b.prerelease[i];
        const xn = /^\d+$/.test(x), yn = /^\d+$/.test(y);
        if (x === y)
            continue;
        if (xn && yn)
            return Number(x) < Number(y) ? -1 : 1;
        if (xn !== yn)
            return xn ? -1 : 1;
        return x < y ? -1 : 1;
    }
    return a.prerelease.length - b.prerelease.length;
}

export function tagVersion(tag) {
    let version = tag.startsWith('jusprin/') ? tag.slice('jusprin/'.length) : tag;
    if (version.startsWith('v'))
        version = version.slice(1);
    return parseVersion(version);
}

export function readVersion(header) {
    const match = /kVersion\[\]\s*=\s*"([^"]*)"/.exec(header);
    if (!match)
        throw new Error('Version.hpp has no kVersion = "X.Y.Z" line');
    const version = parseVersion(match[1]);
    if (!version)
        throw new Error(`Version.hpp's version "${match[1]}" is not X.Y.Z or X.Y.Z-label`);
    return version;
}

export function checkRelease(version, releases) {
    const tag = `v${version.text}`;
    let draftId = '';
    for (const release of releases) {
        const released = tagVersion(release.tag_name ?? '');
        if (!released || compareVersions(released, version) !== 0)
            continue;
        if (!release.draft)
            throw new Error(`JusPrin ${version.text} is already released (${release.tag_name}). Raise the version in Version.hpp.`);
        if (release.tag_name === tag) {
            if (draftId)
                throw new Error(`There are two drafts tagged ${tag}. Delete one.`);
            draftId = String(release.id);
        }
    }
    for (const release of releases) {
        if (release.draft)
            continue;
        const released = tagVersion(release.tag_name ?? '');
        if (released && compareVersions(released, version) > 0)
            throw new Error(`JusPrin ${version.text} is below the released ${released.text} (${release.tag_name}).`);
    }
    return { version: version.text, tag, prerelease: version.prerelease.length > 0, draftId };
}

function main(argv) {
    const [command, headerPath, releasesPath] = argv;
    const version = readVersion(readFileSync(headerPath, 'utf8'));
    if (command === 'version') {
        console.log(version.text);
        return;
    }
    if (command === 'check') {
        const releases = JSON.parse(readFileSync(releasesPath, 'utf8')).flat();
        const result = checkRelease(version, releases);
        console.log(`version=${result.version}`);
        console.log(`tag=${result.tag}`);
        console.log(`prerelease=${result.prerelease}`);
        console.log(`draft_id=${result.draftId}`);
        return;
    }
    throw new Error(`unknown command "${command}"`);
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
    try {
        main(process.argv.slice(2));
    } catch (error) {
        console.error(`::error::${error.message}`);
        process.exit(1);
    }
}

// node --test src/slic3r/GUI/JusPrin/Packaging/release.test.mjs
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { test } from 'node:test';

import { checkRelease, compareVersions, parseVersion, readVersion, tagVersion } from './release.mjs';

const v = (text) => parseVersion(text);
const release = (tag_name, extra = {}) => ({ id: 1, tag_name, draft: false, prerelease: false, ...extra });

// JusPrin's releases on GitHub as of 2026-10-22, newest first.
const published = [
    release('nightly-builds', { prerelease: true }),
    release('jusprin/v1.4.0'),
    release('v1.3.0'),
    release('v1.2.0'),
    release('v0.2.0'),
];

test('reads the version in the checked-in Version.hpp', () => {
    const header = readFileSync(new URL('../Updates/Version.hpp', import.meta.url), 'utf8');
    assert.match(readVersion(header).text, /^\d+\.\d+\.\d+/);
});

test('refuses a Version.hpp without a usable version', () => {
    assert.throws(() => readVersion('inline constexpr char kOther[] = "2.0.0";'));
    assert.throws(() => readVersion('inline constexpr char kVersion[] = "2.0";'));
});

test('orders versions as Semantic Versioning does', () => {
    assert.ok(compareVersions(v('2.0.0'), v('1.4.0')) > 0);
    assert.ok(compareVersions(v('2.0.0-beta1'), v('2.0.0')) < 0);
    assert.ok(compareVersions(v('2.0.0-beta.2'), v('2.0.0-beta.10')) < 0);
    assert.ok(compareVersions(v('2.0.0-beta'), v('2.0.0-beta.1')) < 0);
    assert.ok(compareVersions(v('1.10.0'), v('1.9.0')) > 0);
    assert.equal(compareVersions(v('2.0.0'), v('2.0.0')), 0);
});

test('reads both tag forms and ignores other tags', () => {
    assert.equal(tagVersion('jusprin/v1.4.0').text, '1.4.0');
    assert.equal(tagVersion('v1.3.0').text, '1.3.0');
    assert.equal(tagVersion('nightly-builds'), null);
});

test('2.0.0 can be drafted over the 1.x releases', () => {
    assert.deepEqual(checkRelease(v('2.0.0'), published),
                     { version: '2.0.0', tag: 'v2.0.0', prerelease: false, draftId: '' });
});

test('a test version is drafted as a pre-release', () => {
    assert.equal(checkRelease(v('2.1.0-beta1'), published).prerelease, true);
});

test('an existing draft for the tag is reused', () => {
    const releases = [release('v2.0.0', { id: 42, draft: true }), ...published];
    assert.equal(checkRelease(v('2.0.0'), releases).draftId, '42');
});

test('a released version is never built again', () => {
    assert.throws(() => checkRelease(v('1.4.0'), published), /already released/);
    assert.throws(() => checkRelease(v('2.0.0'), [release('v2.0.0'), ...published]), /already released/);
});

test('a version below a published one is refused', () => {
    assert.throws(() => checkRelease(v('1.3.5'), published), /below the released 1.4.0/);
    assert.throws(() => checkRelease(v('2.0.0-rc1'), [release('v2.0.0'), ...published]), /below/);
});

test('two drafts for one tag are refused', () => {
    const releases = [release('v2.0.0', { id: 1, draft: true }), release('v2.0.0', { id: 2, draft: true })];
    assert.throws(() => checkRelease(v('2.0.0'), releases), /two drafts/);
});

# Makes JusPrin's Windows installer and portable zip from a finished build.
#
#   windows_package.ps1 -BuildDir build -Version 2.0.0 -Arch x64 -OutDir dist
#
# The installer comes from OrcaSlicer's CPack setup, whose name, version and
# uninstall key packaging.cmake replaces with JusPrin's. The portable zip is
# OrcaSlicer's install folder (build\OrcaSlicer) under JusPrin's name.
param(
    [Parameter(Mandatory)] [string] $BuildDir,
    [Parameter(Mandatory)] [string] $Version,
    [Parameter(Mandatory)] [string] $Arch,
    [Parameter(Mandatory)] [string] $OutDir,
