// Structural checks for the JusPrin release workflows (no actionlint here).
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import YAML from 'yaml';

const repo = process.argv[2];
const wf = (name) => {
    const doc = YAML.parseDocument(readFileSync(join(repo, '.github/workflows', name), 'utf8'));
    if (doc.errors.length) throw new Error(`${name}: ${doc.errors.join('; ')}`);
    return doc.toJS();
};
const problems = [];
const fail = (msg) => problems.push(msg);

function walkStrings(node, path, visit) {
    if (typeof node === 'string') visit(node, path);
    else if (Array.isArray(node)) node.forEach((n, i) => walkStrings(n, `${path}[${i}]`, visit));
    else if (node && typeof node === 'object') for (const [k, v] of Object.entries(node)) walkStrings(v, `${path}.${k}`, visit);
}

function check(name) {
    const w = wf(name);
    const jobs = w.jobs;
    const callInputs = w.on?.workflow_call?.inputs ?? {};
    const dispatchInputs = w.on?.workflow_dispatch?.inputs ?? {};
    for (const [id, job] of Object.entries(jobs)) {
        const needs = [job.needs ?? []].flat();
        for (const n of needs) if (!jobs[n]) fail(`${name}:${id} needs unknown job ${n}`);
        walkStrings(job, `${name}:${id}`, (s, path) => {
            const opens = (s.match(/\$\{\{/g) ?? []).length, closes = (s.match(/\}\}/g) ?? []).length;
            if (opens !== closes) fail(`${path}: unbalanced \${{ }}`);
            for (const m of s.matchAll(/needs\.([A-Za-z_][\w-]*)\.(outputs\.([\w-]+)|result)/g)) {
                if (!needs.includes(m[1])) fail(`${path}: uses needs.${m[1]} without needing it`);
                else if (m[3] && !(jobs[m[1]].outputs && m[3] in jobs[m[1]].outputs))
                    fail(`${path}: needs.${m[1]}.outputs.${m[3]} is not declared`);
            }
            for (const m of s.matchAll(/\binputs\.([\w-]+)/g))
                if (!(m[1] in callInputs) && !(m[1] in dispatchInputs)) fail(`${path}: inputs.${m[1]} is not declared`);
            for (const m of s.matchAll(/steps\.([\w-]+)\.outputs/g))
                if (!(job.steps ?? []).some((st) => st.id === m[1])) fail(`${path}: no step with id ${m[1]}`);
            for (const m of s.matchAll(/matrix\.([\w-]+)/g)) {
                const keys = new Set((job.strategy?.matrix?.include ?? []).flatMap(Object.keys));
