const get = async (url) => {
    const r = await fetch(url, { headers: { 'User-Agent': 'jusprin-dry-run-watch', Accept: 'application/vnd.github+json' } });
    if (!r.ok) throw new Error(`${r.status} ${url}`);
    return r.json();
};
for (;;) {
    try {
        const jobs = await get(`${api}/jobs?per_page=100&filter=latest`);
        for (const j of jobs.jobs) {
            const state = `${j.status}/${j.conclusion ?? ''}`;
            if (seen.get(j.name) !== state) {
                seen.set(j.name, state);
                const failed = (j.steps ?? []).filter((s) => s.conclusion === 'failure').map((s) => s.name);
                console.log(`${j.name}: ${state}${failed.length ? ` failed step: ${failed.join(', ')}` : ''}`);
            }
        }
        const run = await get(api);
        if (run.status === 'completed') {
            console.log(`RUN ${run.status}/${run.conclusion}`);
            process.exit(0);
        }
    } catch (e) {
        console.log(`poll error: ${e.message}`);
    }
    await new Promise((r) => setTimeout(r, Number(interval) * 1000));
}

